package br.com.loja.order;import br.com.loja.order.dto.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orders")public class OrderController{private final OrderService service;public OrderController(OrderService s){service=s;}@GetMapping public List<CustomerOrder> list(Authentication a){boolean admin=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));return service.list(a.getName(),admin);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public CustomerOrder checkout(@Valid @RequestBody CheckoutRequest q,Authentication a){return service.checkout(q,a.getName());}@PatchMapping("/{id}/status")@PreAuthorize("hasRole('ADMIN')")public CustomerOrder status(@PathVariable Long id,@RequestBody Map<String,String> body){return service.status(id,OrderStatus.valueOf(body.get("status")));}}